<div class="d-flex justify-content-between align-items-center flex-wrap gap-2 mb-3"><h1 class="h4 mb-0">Auditoria</h1>
  <form method="get" class="d-flex gap-2"><input type="search" name="q" class="form-control form-control-sm" value="<?= e($filters['q']) ?>" placeholder="Pessoa, entidade, dado"><select name="acao" class="form-select form-select-sm" data-autosubmit><option value="">Todas as ações</option><?php foreach ($actions as $ac): ?><option value="<?= e($ac) ?>"<?= selected($ac, $filters['action']) ?>><?= e($ac) ?></option><?php endforeach; ?></select><button class="btn btn-sm btn-outline-primary"><i class="bi bi-search"></i></button></form></div>
<div class="card"><div class="table-responsive"><table class="table table-sm table-hover mb-0 small"><thead class="table-light"><tr><th>Quando</th><th>Quem</th><th>Ação</th><th>Entidade</th><th>Dados</th><th>IP</th></tr></thead><tbody>
<?php if (!$result['itens']): ?><tr><td colspan="6" class="text-center text-muted py-4">Nenhum registro.</td></tr><?php endif; ?>
<?php foreach ($result['itens'] as $l): ?><tr><td class="text-nowrap"><?= e(format_datetime($l['created_at'])) ?></td><td><?= e($l['user_name'] ?? '—') ?></td><td><code><?= e($l['action']) ?></code></td><td><?= e($l['entity']) ?><?= $l['entity_id'] ? ' #' . e($l['entity_id']) : '' ?></td><td class="text-break"><?= e(truncate((string) ($l['after_data'] ?? $l['before_data'] ?? ''), 140)) ?></td><td class="text-muted"><?= e($l['ip']) ?></td></tr><?php endforeach; ?>
</tbody></table></div></div>
<?php partial('pagination', ['result' => $result]) ?>
